use super::*;
#[path="../../../../📸️snapshot/🧳️state/🧪️tests/🧰️helpers/🦀️.rs"]mod helpers;
use helpers::{receive,source,grant,observe,drain,denied_axes};
use crate::snapshot::state::StateShadingSurface;
#[derive(semio_framework_value::RetireOwned)]struct Payload{id:crate::model::EntityId,name:String,vertices_m:Vec<[f64;3]>,transmittance_schedule_id:Option<crate::schedule::ScheduleId>}
struct Name;impl RowFieldSource for Name{type Payload=Payload;type Value=String;fn field(p:RetainedCloneRef<'_,Payload>)->RetainedCloneRef<'_,String>{p.project(0,|p|&p.name)}}
struct Vertices;impl RowFieldSource for Vertices{type Payload=Payload;type Value=Vec<[f64;3]>;fn field(p:RetainedCloneRef<'_,Payload>)->RetainedCloneRef<'_,Self::Value>{p.project(1,|p|&p.vertices_m)}}
struct Schedule;impl RowFieldSource for Schedule{type Payload=Payload;type Value=Option<crate::schedule::ScheduleId>;fn field(p:RetainedCloneRef<'_,Payload>)->RetainedCloneRef<'_,Self::Value>{p.project(2,|p|&p.transmittance_schedule_id)}}
struct Shading;
impl RowBirthSpec for Shading{
 type Payload=Payload;type Context=();type Row=StateShadingSurface;type Fields=RowFieldsPair<Payload,SealedRowField<Name>,RowFieldsPair<Payload,SealedRowField<Vertices>,SealedRowField<Schedule>>>;
 fn finish(p:RetainedCloneRef<'_,Payload>,(name,(vertices_m,transmittance_schedule_id)):<Self::Fields as RowFieldsPreparation<Payload>>::Fields,_:())->StateShadingSurface{StateShadingSurface{id:p.get().id,name,vertices_m,transmittance_schedule_id}}
}
#[test]
fn typed_row_birth_preserves_original_fields_exact_fragment_receipts_and_all_cancellation_prefixes(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for wide in [false,true]{let p=&law["payload"];let vertices=if wide{vec![receive::<[f64;3]>(&law["wide"]["point"]);law["wide"]["vertices"].as_u64().unwrap()as usize]}else{receive::<Vec<[f64;3]>>(&p["vertices_m"])};let original=source(Payload{id:crate::model::EntityId(p["id"].as_u64().unwrap()as u32),name:p["name"].as_str().unwrap().into(),vertices_m:vertices,transmittance_schedule_id:None});
 for cut in std::iter::once(None).chain(law["cancelAt"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize))){let mut owner=RowBirthPreparation::<Shading>::new();for _ in 0..cut.unwrap_or(10000){if owner.ready(){break;}let d=owner.demand(original.borrow(),4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.advance(original.borrow(),4096,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.demand(original.borrow(),4096).unwrap(),d);}let(s,h)=observe(||owner.advance(original.borrow(),4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}
 if cut.is_none(){assert!(owner.ready());let g=grant(owner.take_demand().unwrap());let((row,p),h)=observe(||owner.take(g).unwrap().unwrap());assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(row.get().id,original.borrow().get().id);assert_eq!(row.get().name.get(),&original.borrow().get().name);assert_eq!(row.get().vertices_m.get(),&original.borrow().get().vertices_m);assert_eq!(row.get().transmittance_schedule_id.get(),&None);drain(row);}
 owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){break;}let d=owner.close_demand(4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.close_step(denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.close_demand(4096).unwrap(),d);}let(s,h)=observe(||owner.close_step(g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));}drain(original);}
}

#[derive(semio_framework_value::RetireOwned)]struct Recreated{id:u32,name:String,vertices_m:Vec<[f64;3]>,rank:usize}
struct OldName;impl RowFieldSource for OldName{type Payload=StateShadingSurface;type Value=String;fn field(p:RetainedCloneRef<'_,Self::Payload>)->RetainedCloneRef<'_,String>{p.project(0,|p|p.name.get())}}
struct OldVertices;impl RowFieldSource for OldVertices{type Payload=StateShadingSurface;type Value=Vec<[f64;3]>;fn field(p:RetainedCloneRef<'_,Self::Payload>)->RetainedCloneRef<'_,Self::Value>{p.project(1,|p|p.vertices_m.get())}}
struct Recreate;
impl RowBirthSpec for Recreate{type Payload=StateShadingSurface;type Context=usize;type Row=Recreated;type Fields=RowFieldsPair<StateShadingSurface,OwnedRowField<OldName>,OwnedRowField<OldVertices>>;fn finish(p:RetainedCloneRef<'_,Self::Payload>,(name,vertices_m):<Self::Fields as RowFieldsPreparation<Self::Payload>>::Fields,rank:usize)->Recreated{Recreated{id:p.get().id.0,name,vertices_m,rank}}}
#[test]
fn original_owned_inverse_record_reconstructs_real_fields_and_admitted_rank_without_sealed_temporary(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let original=source(receive::<StateShadingSurface>(&law["payload"]));let rank=law["rank"].as_u64().unwrap()as usize;
 for cut in std::iter::once(None).chain(law["cancelAt"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize))){let mut owner=RowBirthPreparation::<Recreate,OwnedRecordForm>::with_context(rank);for _ in 0..cut.unwrap_or(10000){if owner.ready(){break;}let d=owner.demand(original.borrow(),4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.advance(original.borrow(),4096,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));}let(s,h)=observe(||owner.advance(original.borrow(),4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}if cut.is_none(){assert!(owner.ready());let g=grant(owner.take_demand().unwrap());let((row,p),h)=observe(||owner.take(g).unwrap().unwrap());assert!(p.fits(g));assert_eq!(h,(0,0));assert_eq!(row.id,original.borrow().get().id.0);assert_eq!(&row.name,original.borrow().get().name.get());assert_eq!(&row.vertices_m,original.borrow().get().vertices_m.get());assert_eq!(row.rank,rank);drain(row);}owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){break;}let d=owner.close_demand(4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.close_step(denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));}let(s,h)=observe(||owner.close_step(g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));}drain(original);
}
